package com.andye.warmod.rocket;import com.andye.warmod.WarMod;import com.andye.warmod.entity.RocketProjectileEntity;import com.andye.warmod.testtool.TestExplosionService;import com.andye.warmod.warhead.WarheadImpactService;import java.util.UUID;import net.minecraft.SharedConstants;import net.minecraft.core.BlockPos;import net.minecraft.core.particles.ParticleTypes;import net.minecraft.server.level.ServerLevel;import net.minecraft.server.level.ServerPlayer;import net.minecraft.sounds.SoundEvents;import net.minecraft.sounds.SoundSource;import net.minecraft.world.phys.Vec3;public final class RocketImpactService {private RocketImpactService(){}public static void impact(ServerLevel level,RocketProjectileEntity rocket,Vec3 position){ServerPlayer owner=rocket.ownerId()==null?null:level.getServer().getPlayerList().getPlayer(rocket.ownerId());if(owner!=null&&owner.level()!=level)owner=null;if(rocket.payloadType()==RocketPayloadType.HE){TestExplosionService.createExplosion(level,owner,position,RocketConstants.EXPLOSION_STRENGTH);level.playSound(null,BlockPos.containing(position),SoundEvents.GENERIC_EXPLODE.value(),SoundSource.BLOCKS,1.35F,1F);level.sendParticles(ParticleTypes.SMOKE,position.x,position.y,position.z,18,.6,.45,.6,.08);level.sendParticles(ParticleTypes.FLAME,position.x,position.y,position.z,10,.45,.35,.45,.06);}else{UUID id=rocket.getUUID();WarheadImpactService.detonateAt(level,owner,id,id,position,rocket.visualSeed(),rocket.payloadType().warhead(),false);}if(SharedConstants.IS_RUNNING_IN_IDE)WarMod.LOGGER.info("Rocket {} impacted: payload={}, position={}",rocket.getUUID(),rocket.payloadType(),position);}}